INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What term describes the largest number of individuals an ecosystem can support sustainably over time without damaging its resources?', NULL, NULL, NULL, NULL, 'Carrying capacity', 'The correct term is: Carrying capacity.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What do we call any factor that limits or stops a population from growing further?', NULL, NULL, NULL, NULL, 'Limiting factor', 'The correct term is: Limiting factor.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Which of these is not a typical limiting factor for animal populations: food, water, shelter, or body color?', NULL, NULL, NULL, NULL, 'Body color of individuals', 'The correct term is: Body color of individuals.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What name is given to rapid, unrestricted population growth that produces a steep upward curve?', NULL, NULL, NULL, NULL, 'Exponential growth / J-shaped curve', 'The correct term is: Exponential growth / J-shaped curve.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What happens to a population’s growth rate as it gets close to the carrying capacity of its environment?', NULL, NULL, NULL, NULL, 'It slows down and approaches zero', 'The correct term is: It slows down and approaches zero.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What is the term for the growth pattern that rises quickly then levels off smoothly at carrying capacity?', NULL, NULL, NULL, NULL, 'Logistic growth', 'The correct term is: Logistic growth.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What effect does a shortage of available mates have on the size of a small population?', NULL, NULL, NULL, NULL, 'It limits population growth', 'The correct term is: It limits population growth.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What does the flat, horizontal section at the top of a logistic growth curve stand for?', NULL, NULL, NULL, NULL, 'Carrying capacity / stable population size', 'The correct term is: Carrying capacity / stable population size.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Drought reduces food and water, causing rabbit numbers to drop sharply. What kind of factor is drought in this case?', NULL, NULL, NULL, NULL, 'Limiting factor', 'The correct term is: Limiting factor.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What phrase refers to the count of individuals living within a specific unit of area or volume?', NULL, NULL, NULL, NULL, 'Population density', 'The correct term is: Population density.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'A forest normally supports 500 deer. After a typhoon destroys many trees, what will happen to its carrying capacity?', NULL, NULL, NULL, NULL, 'It will decrease', 'The correct term is: It will decrease.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What type of limiting factor has a stronger effect when a population is large and crowded?', NULL, NULL, NULL, NULL, 'Density-dependent limiting factor', 'The correct term is: Density-dependent limiting factor.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What type of limiting factor affects populations regardless of whether they are dense or sparse?', NULL, NULL, NULL, NULL, 'Density-independent limiting factor', 'The correct term is: Density-independent limiting factor.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What is the main reason population growth slows as it nears carrying capacity?', NULL, NULL, NULL, NULL, 'Competition for resources becomes more intense', 'The correct term is: Competition for resources becomes more intense.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Rats increase in number, so snakes that eat them also rise, slowing rat population growth. Predation acts as what kind of limiting factor?', NULL, NULL, NULL, NULL, 'Biotic limiting factor', 'The correct term is: Biotic limiting factor.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'In nature, what eventually happens to a population showing J-shaped exponential growth?', NULL, NULL, NULL, NULL, 'Limiting factors stop growth; it either crashes or levels into an S-shaped curve', 'The correct term is: Limiting factors stop growth; it either crashes or levels into an S-shaped curve.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'If a population is smaller than the environment’s carrying capacity, how will its size usually change?', NULL, NULL, NULL, NULL, 'It will increase until it approaches carrying capacity', 'The correct term is: It will increase until it approaches carrying capacity.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Building a landfill destroys most of a frog’s breeding pond. Which limiting factor is most reduced?', NULL, NULL, NULL, NULL, 'Shelter / breeding space', 'The correct term is: Shelter / breeding space.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Which pair consists only of abiotic (non-living) limiting factors?', NULL, NULL, NULL, NULL, 'Water availability and temperature extremes', 'The correct term is: Water availability and temperature extremes.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Which growth pattern best matches the current human population?', NULL, NULL, NULL, NULL, 'Rising J-shaped curve / early logistic growth', 'The correct term is: Rising J-shaped curve / early logistic growth.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Arrange the stages of logistic growth in the correct order.', NULL, NULL, NULL, NULL, 'Slow initial growth → rapid exponential growth → slowing growth → stable at carrying', 'The correct term is: Slow initial growth → rapid exponential growth → slowing growth → stable at carrying.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What usually happens after a population temporarily exceeds its carrying capacity?', NULL, NULL, NULL, NULL, 'Population crash or sharp decline due to resource shortage', 'The correct term is: Population crash or sharp decline due to resource shortage.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'A lake can support 1,000 tilapia. If 1,200 are added, what will most likely happen?', NULL, NULL, NULL, NULL, 'Many will die; numbers will settle back near 1,000', 'The correct term is: Many will die; numbers will settle back near 1,000.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Why is the availability of mates especially important for small, isolated groups?', NULL, NULL, NULL, NULL, 'It reduces the chance of successful reproduction', 'The correct term is: It reduces the chance of successful reproduction.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'What is the key difference between density-dependent and density-independent limiting factors?', NULL, NULL, NULL, NULL, 'Density-dependent impact rises with crowding; density-independent impact is the same', 'The correct term is: Density-dependent impact rises with crowding; density-independent impact is the same.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Give an example that shows growth slowing as it nears carrying capacity.', NULL, NULL, NULL, NULL, 'Mouse numbers change from 100 → 180 → 210 → 215 → 212', 'The correct term is: Mouse numbers change from 100 → 180 → 210 → 215 → 212.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'How does competition limit population size near carrying capacity?', NULL, NULL, NULL, NULL, 'Fewer individuals survive and reproduce because resources become scarce', 'The correct term is: Fewer individuals survive and reproduce because resources become scarce.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Protecting both food sources and nesting sites will raise the carrying capacity of the Philippine Eagle. What does this show about carrying capacity?', NULL, NULL, NULL, NULL, 'It depends on multiple limiting factors working together', 'The correct term is: It depends on multiple limiting factors working together.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Why can exponential growth never continue indefinitely in any real ecosystem?', NULL, NULL, NULL, NULL, 'All natural resources are finite', 'The correct term is: All natural resources are finite.', true),
('b0000000-0000-0000-0000-000000000201', 3, 'post_test', 'Under what condition does a population remain stable at carrying capacity?', NULL, NULL, NULL, NULL, 'When birth rate is roughly equal to death rate', 'The correct term is: When birth rate is roughly equal to death rate.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What is the general term for using living things or biological processes to create useful goods?', NULL, NULL, NULL, NULL, 'Biotechnology', 'The correct term is: Biotechnology.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What process forms the basis of traditional biotechnology used to make foods like cheese and vinegar?', NULL, NULL, NULL, NULL, 'Fermentation', 'The correct term is: Fermentation.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What Filipino food product is made when bacteria ferment coconut water?', NULL, NULL, NULL, NULL, 'Nata de coco', 'The correct term is: Nata de coco.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What acid is produced when alcohol is further oxidized to form vinegar?', NULL, NULL, NULL, NULL, 'Acetic acid', 'The correct term is: Acetic acid.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What acid is produced by bacteria to make yogurt, cheese, and pickles?', NULL, NULL, NULL, NULL, 'Lactic acid', 'The correct term is: Lactic acid.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What main ingredients are fermented to produce soy sauce?', NULL, NULL, NULL, NULL, 'Soybeans and usually wheat or grain', 'The correct term is: Soybeans and usually wheat or grain.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What part of an organism is deliberately altered to create a Genetically Modified Organism?', NULL, NULL, NULL, NULL, 'DNA / genetic material', 'The correct term is: DNA / genetic material.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What does “in vitro” mean in the process of In Vitro Fertilization?', NULL, NULL, NULL, NULL, 'Fertilization happens outside the body in a laboratory', 'The correct term is: Fertilization happens outside the body in a laboratory.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What is one common benefit of genetically modified crops?', NULL, NULL, NULL, NULL, 'Pest resistance / higher yield / reduced pesticide use', 'The correct term is: Pest resistance / higher yield / reduced pesticide use.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What is one major ethical concern linked to IVF?', NULL, NULL, NULL, NULL, 'Moral status of embryos / cost and fair access', 'The correct term is: Moral status of embryos / cost and fair access.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'Which list contains only products made using traditional fermentation?', NULL, NULL, NULL, NULL, 'Cheese, soy sauce, vinegar, nata de coco, yogurt', 'The correct term is: Cheese, soy sauce, vinegar, nata de coco, yogurt.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What gas does yeast produce that makes bread rise?', NULL, NULL, NULL, NULL, 'Carbon dioxide', 'The correct term is: Carbon dioxide.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'Golden Rice is modified to produce high levels of what nutrient to prevent blindness?', NULL, NULL, NULL, NULL, 'Beta-carotene (Vitamin A precursor)', 'The correct term is: Beta-carotene (Vitamin A precursor).', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What is one possible environmental risk of planting insect-resistant GMO crops?', NULL, NULL, NULL, NULL, 'Pests may develop resistance / harm to beneficial insects', 'The correct term is: Pests may develop resistance / harm to beneficial insects.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What is one economic concern regarding GMO seeds in the Philippines?', NULL, NULL, NULL, NULL, 'High cost and corporate control affecting small farmers', 'The correct term is: High cost and corporate control affecting small farmers.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'How is human insulin for diabetes produced using modern biotechnology?', NULL, NULL, NULL, NULL, 'The human insulin gene is inserted into bacteria that make the insulin', 'The correct term is: The human insulin gene is inserted into bacteria that make the insulin.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'Which microbe is responsible for turning alcohol into acetic acid?', NULL, NULL, NULL, NULL, 'Acetic acid bacteria', 'The correct term is: Acetic acid bacteria.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'Why is fermentation considered an ancient form of biotechnology?', NULL, NULL, NULL, NULL, 'It was used for thousands of years before microbes were discovered', 'The correct term is: It was used for thousands of years before microbes were discovered.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What is true about the genetic makeup of an organism produced by cloning?', NULL, NULL, NULL, NULL, 'It is genetically identical to the donor parent', 'The correct term is: It is genetically identical to the donor parent.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What is one major ethical concern about using gene-editing tools like CRISPR on humans?', NULL, NULL, NULL, NULL, 'Risk of unintended genetic changes / creation of “designer babies”', 'The correct term is: Risk of unintended genetic changes / creation of “designer babies”.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What is the correct two-step process for making traditional vinegar?', NULL, NULL, NULL, NULL, 'Sugar → (yeast) → ethanol → (bacteria) → acetic acid', 'The correct term is: Sugar → (yeast) → ethanol → (bacteria) → acetic acid.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What material forms the solid jelly part of nata de coco?', NULL, NULL, NULL, NULL, 'Bacterial cellulose', 'The correct term is: Bacterial cellulose.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What international agreement governs the safe handling and movement of living GMOs?', NULL, NULL, NULL, NULL, 'Cartagena Protocol', 'The correct term is: Cartagena Protocol.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What is one environmental benefit of some approved GMO crops?', NULL, NULL, NULL, NULL, 'Less insecticide use and reduced chemical pollution', 'The correct term is: Less insecticide use and reduced chemical pollution.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What issue involves both ethics and economics regarding IVF in the Philippines?', NULL, NULL, NULL, NULL, 'High cost makes it unavailable to many people', 'The correct term is: High cost makes it unavailable to many people.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'How does fermentation help preserve food?', NULL, NULL, NULL, NULL, 'It produces acids or alcohol that stop harmful microbes from growing', 'The correct term is: It produces acids or alcohol that stop harmful microbes from growing.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'Where does the gene that gives Bt corn its pest-killing ability come from?', NULL, NULL, NULL, NULL, 'The bacterium Bacillus thuringiensis', 'The correct term is: The bacterium Bacillus thuringiensis.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What is the main difference between traditional and modern biotechnology?', NULL, NULL, NULL, NULL, 'Traditional uses natural processes; modern directly modifies DNA in a lab', 'The correct term is: Traditional uses natural processes; modern directly modifies DNA in a lab.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'What ethical concern arises because several embryos are created during IVF?', NULL, NULL, NULL, NULL, 'What happens to unused or extra embryos', 'The correct term is: What happens to unused or extra embryos.', true),
('b0000000-0000-0000-0000-000000000202', 3, 'post_test', 'Give one example of a practice that can be done using both traditional and modern biotechnology.', NULL, NULL, NULL, NULL, 'Plant breeding', 'The correct term is: Plant breeding.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What theory states that Earth’s outer layer is made of large moving slabs of rock?', NULL, NULL, NULL, NULL, 'Plate Tectonics', 'The correct term is: Plate Tectonics.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What name is given to these large moving slabs?', NULL, NULL, NULL, NULL, 'Tectonic / lithospheric plates', 'The correct term is: Tectonic / lithospheric plates.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'Approximately how fast do tectonic plates move each year?', NULL, NULL, NULL, NULL, 'About 2–10 centimeters per year (as fast as fingernails grow)', 'The correct term is: About 2–10 centimeters per year (as fast as fingernails grow).', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What modern technology is used to measure plate movement accurately?', NULL, NULL, NULL, NULL, 'GPS satellites', 'The correct term is: GPS satellites.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What kind of boundary forms where plates move apart?', NULL, NULL, NULL, NULL, 'Divergent boundary', 'The correct term is: Divergent boundary.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What kind of boundary forms where plates collide?', NULL, NULL, NULL, NULL, 'Convergent boundary', 'The correct term is: Convergent boundary.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What kind of boundary forms where plates slide past each other?', NULL, NULL, NULL, NULL, 'Transform fault boundary', 'The correct term is: Transform fault boundary.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What layer of the mantle allows plates to move over it?', NULL, NULL, NULL, NULL, 'Asthenosphere', 'The correct term is: Asthenosphere.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What process occurs when one plate sinks beneath another into the mantle?', NULL, NULL, NULL, NULL, 'Subduction', 'The correct term is: Subduction.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What is the name of the major fault system running through the Philippines?', NULL, NULL, NULL, NULL, 'Philippine Fault System', 'The correct term is: Philippine Fault System.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What landform is created when two continents collide?', NULL, NULL, NULL, NULL, 'Large non-volcanic mountain ranges', 'The correct term is: Large non-volcanic mountain ranges.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What features form when an oceanic plate subducts under a continental plate?', NULL, NULL, NULL, NULL, 'Deep ocean trench and volcanic mountains on land', 'The correct term is: Deep ocean trench and volcanic mountains on land.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'Between which two major plates does the Philippines lie?', NULL, NULL, NULL, NULL, 'Philippine Sea Plate and Eurasian Plate', 'The correct term is: Philippine Sea Plate and Eurasian Plate.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'Why does the Philippines have many volcanoes and trenches?', NULL, NULL, NULL, NULL, 'Multiple plates are subducting around the archipelago', 'The correct term is: Multiple plates are subducting around the archipelago.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What geologic event is most common at transform boundaries?', NULL, NULL, NULL, NULL, 'Earthquakes', 'The correct term is: Earthquakes.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'How were the Himalayan Mountains formed?', NULL, NULL, NULL, NULL, 'Collision of the Indian Plate with the Eurasian Plate', 'The correct term is: Collision of the Indian Plate with the Eurasian Plate.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'How did the Andes Mountains form?', NULL, NULL, NULL, NULL, 'Subduction of the Nazca Plate under the South American Plate', 'The correct term is: Subduction of the Nazca Plate under the South American Plate.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What is the main force that drives plate movement?', NULL, NULL, NULL, NULL, 'Thermal convection currents in the mantle', 'The correct term is: Thermal convection currents in the mantle.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What happens to the overriding plate when another plate subducts beneath it?', NULL, NULL, NULL, NULL, 'Magma rises to form volcanoes; folding and faulting create mountains', 'The correct term is: Magma rises to form volcanoes; folding and faulting create mountains.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'Where are new sections of ocean floor created?', NULL, NULL, NULL, NULL, 'At divergent boundaries / mid-ocean ridges', 'The correct term is: At divergent boundaries / mid-ocean ridges.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'If the Philippine Sea Plate keeps moving northwest, where will the Philippines be in 50 million years?', NULL, NULL, NULL, NULL, 'About 3,500 km northwest, joining the eastern edge of Asia', 'The correct term is: About 3,500 km northwest, joining the eastern edge of Asia.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'Why is GPS preferred over older methods for measuring plate motion?', NULL, NULL, NULL, NULL, 'It gives highly precise, continuous, global measurements', 'The correct term is: It gives highly precise, continuous, global measurements.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What process formed the Mariana Trench and Philippine Trench?', NULL, NULL, NULL, NULL, 'Subduction', 'The correct term is: Subduction.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What type of boundary created Mayon Volcano and the Manila Trench?', NULL, NULL, NULL, NULL, 'Convergent boundary', 'The correct term is: Convergent boundary.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'Why do no volcanoes form when two continental plates collide?', NULL, NULL, NULL, NULL, 'Continental crust is too light to sink and melt', 'The correct term is: Continental crust is too light to sink and melt.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What property allows the asthenosphere to flow slowly and move the plates?', NULL, NULL, NULL, NULL, 'It is solid rock that is soft and flexible over very long periods', 'The correct term is: It is solid rock that is soft and flexible over very long periods.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What does having trenches on both sides of the Philippines tell us about its tectonic setting?', NULL, NULL, NULL, NULL, 'It is squeezed between two sets of subducting plates', 'The correct term is: It is squeezed between two sets of subducting plates.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What kind of fault is the Philippine Fault System?', NULL, NULL, NULL, NULL, 'Left-lateral transform fault', 'The correct term is: Left-lateral transform fault.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'What is the difference between landforms formed by ocean-ocean and ocean-continent subduction?', NULL, NULL, NULL, NULL, 'Ocean-ocean forms volcanic island arcs; ocean-continent forms volcanic mountains on', 'The correct term is: Ocean-ocean forms volcanic island arcs; ocean-continent forms volcanic mountains on.', true),
('b0000000-0000-0000-0000-000000000203', 3, 'post_test', 'If we reversed plate motion 50 million years ago, where would India and the Philippines be?', NULL, NULL, NULL, NULL, 'India was an island south of Asia; the Philippines was separate volcanic islands', 'The correct term is: India was an island south of Asia; the Philippines was separate volcanic islands.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What term describes the average weather pattern of an area over many years?', NULL, NULL, NULL, NULL, 'Climate', 'The correct term is: Climate.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What is the gradual rise in Earth’s average surface temperature called?', NULL, NULL, NULL, NULL, 'Global warming', 'The correct term is: Global warming.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What broader term includes warming plus changes in rainfall, storms, and seasons?', NULL, NULL, NULL, NULL, 'Climate change', 'The correct term is: Climate change.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What name is given to gases that trap heat in the atmosphere?', NULL, NULL, NULL, NULL, 'Greenhouse gases', 'The correct term is: Greenhouse gases.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What is the main human-caused greenhouse gas driving modern warming?', NULL, NULL, NULL, NULL, 'Carbon dioxide (CO₂)', 'The correct term is: Carbon dioxide (CO₂).', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'Name two natural greenhouse gases that keep Earth warm enough for life.', NULL, NULL, NULL, NULL, 'Water vapor and carbon dioxide', 'The correct term is: Water vapor and carbon dioxide.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What does the “enhanced greenhouse effect” mean?', NULL, NULL, NULL, NULL, 'Extra greenhouse gases from human activities trap more heat than normal', 'The correct term is: Extra greenhouse gases from human activities trap more heat than normal.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What direct effect do melting glaciers and ice sheets have on oceans?', NULL, NULL, NULL, NULL, 'Sea level rise', 'The correct term is: Sea level rise.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What do ice core samples show about carbon dioxide levels today compared to the past 800,000 years?', NULL, NULL, NULL, NULL, 'They are far higher than any previous natural level', 'The correct term is: They are far higher than any previous natural level.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'Aside from melting ice, what other process causes sea levels to rise?', NULL, NULL, NULL, NULL, 'Thermal expansion of seawater as it warms', 'The correct term is: Thermal expansion of seawater as it warms.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'Which list contains only major greenhouse gases?', NULL, NULL, NULL, NULL, 'Carbon dioxide, methane, nitrous oxide, CFCs, water vapor', 'The correct term is: Carbon dioxide, methane, nitrous oxide, CFCs, water vapor.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What human activities produce large amounts of methane?', NULL, NULL, NULL, NULL, 'Livestock, rice farming, landfills, leaking natural gas', 'The correct term is: Livestock, rice farming, landfills, leaking natural gas.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What two harmful effects do CFCs cause?', NULL, NULL, NULL, NULL, 'They trap heat and destroy the ozone layer', 'The correct term is: They trap heat and destroy the ozone layer.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'Give three long-term signs that climate change is happening.', NULL, NULL, NULL, NULL, 'Rising temperatures, shrinking ice, rising sea levels', 'The correct term is: Rising temperatures, shrinking ice, rising sea levels.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'How does cutting down forests worsen global warming?', NULL, NULL, NULL, NULL, 'It releases stored carbon and removes trees that absorb CO₂', 'The correct term is: It releases stored carbon and removes trees that absorb CO₂.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'Is a single hot day or one storm enough proof of climate change?', NULL, NULL, NULL, NULL, 'No; climate change requires long-term trends over many years', 'The correct term is: No; climate change requires long-term trends over many years.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What is the correct sequence of events leading to human-caused warming?', NULL, NULL, NULL, NULL, 'Burning fossil fuels → extra CO₂ → stronger greenhouse effect → higher temperatures', 'The correct term is: Burning fossil fuels → extra CO₂ → stronger greenhouse effect → higher temperatures.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'Why will warming continue for decades even if all emissions stop now?', NULL, NULL, NULL, NULL, 'Greenhouse gases stay in the air for a long time and oceans hold heat', 'The correct term is: Greenhouse gases stay in the air for a long time and oceans hold heat.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What human activity produces the most greenhouse gases?', NULL, NULL, NULL, NULL, 'Burning fossil fuels for energy and transport', 'The correct term is: Burning fossil fuels for energy and transport.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'How do scientists confirm that extra CO₂ comes from burning fossil fuels?', NULL, NULL, NULL, NULL, 'Its chemical makeup matches carbon from coal, oil, and gas', 'The correct term is: Its chemical makeup matches carbon from coal, oil, and gas.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What is the difference between the natural and enhanced greenhouse effect?', NULL, NULL, NULL, NULL, 'Natural keeps Earth livable; enhanced is caused by humans and warms the planet too', 'The correct term is: Natural keeps Earth livable; enhanced is caused by humans and warms the planet too.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What kind of feedback loop happens when melting sea ice leads to more heat being absorbed?', NULL, NULL, NULL, NULL, 'Positive feedback', 'The correct term is: Positive feedback.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'Why is a 1°C rise in global average temperature a serious problem?', NULL, NULL, NULL, NULL, 'It causes much larger increases in extreme weather and uneven warming', 'The correct term is: It causes much larger increases in extreme weather and uneven warming.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'How does global warming affect tropical cyclones in the Philippines?', NULL, NULL, NULL, NULL, 'They become stronger and carry more rainfall', 'The correct term is: They become stronger and carry more rainfall.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'Why does the Arctic warm faster than other parts of the world?', NULL, NULL, NULL, NULL, 'Ice-albedo positive feedback: less ice means more sunlight absorbed', 'The correct term is: Ice-albedo positive feedback: less ice means more sunlight absorbed.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'Why can’t natural factors explain the rapid warming seen recently?', NULL, NULL, NULL, NULL, 'Natural factors alone would cause cooling; only human greenhouse gases match the', 'The correct term is: Natural factors alone would cause cooling; only human greenhouse gases match the.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'How does extra CO₂ harm marine life?', NULL, NULL, NULL, NULL, 'It makes seawater more acidic, damaging coral and shellfish', 'The correct term is: It makes seawater more acidic, damaging coral and shellfish.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'Give three observed signs of climate change in the Philippines.', NULL, NULL, NULL, NULL, 'Rising sea levels, stronger typhoons, longer dry spells', 'The correct term is: Rising sea levels, stronger typhoons, longer dry spells.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'Why is water vapor not considered the main cause of modern warming?', NULL, NULL, NULL, NULL, 'It increases because of warming; it does not start the warming', 'The correct term is: It increases because of warming; it does not start the warming.', true),
('b0000000-0000-0000-0000-000000000204', 3, 'post_test', 'What relationship do ice core records show between CO₂ and global temperature?', NULL, NULL, NULL, NULL, 'They rise and fall together; current levels are far higher than natural peaks', 'The correct term is: They rise and fall together; current levels are far higher than natural peaks.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What does the abbreviation ENSO stand for?', NULL, NULL, NULL, NULL, 'El Niño Southern Oscillation', 'The correct term is: El Niño Southern Oscillation.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What is the warm phase of the ENSO cycle called?', NULL, NULL, NULL, NULL, 'El Niño', 'The correct term is: El Niño.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What is the cool phase of the ENSO cycle called?', NULL, NULL, NULL, NULL, 'La Niña', 'The correct term is: La Niña.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'In which ocean basin does the ENSO cycle occur?', NULL, NULL, NULL, NULL, 'Tropical Pacific Ocean', 'The correct term is: Tropical Pacific Ocean.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What are the steady winds that normally blow east to west across the tropical Pacific?', NULL, NULL, NULL, NULL, 'Trade winds', 'The correct term is: Trade winds.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What is the most common effect of El Niño on the Philippines?', NULL, NULL, NULL, NULL, 'Prolonged drought and below-normal rainfall', 'The correct term is: Prolonged drought and below-normal rainfall.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What is the most common effect of La Niña on the Philippines?', NULL, NULL, NULL, NULL, 'Above-normal rain, more floods, and more typhoons', 'The correct term is: Above-normal rain, more floods, and more typhoons.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What does the “Southern Oscillation” part of the name refer to?', NULL, NULL, NULL, NULL, 'Shifts in air pressure between the eastern and western Pacific', 'The correct term is: Shifts in air pressure between the eastern and western Pacific.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'How long do El Niño and La Niña events typically last?', NULL, NULL, NULL, NULL, 'About 9–12 months, sometimes up to 2 years', 'The correct term is: About 9–12 months, sometimes up to 2 years.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'Which agency officially declares El Niño or La Niña in the Philippines?', NULL, NULL, NULL, NULL, 'PAGASA', 'The correct term is: PAGASA.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What happens to trade winds when an El Niño begins?', NULL, NULL, NULL, NULL, 'They weaken or reverse direction', 'The correct term is: They weaken or reverse direction.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What happens to the pool of warm ocean water during El Niño?', NULL, NULL, NULL, NULL, 'It shifts toward the central and eastern Pacific', 'The correct term is: It shifts toward the central and eastern Pacific.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'Why does the Philippines usually get fewer typhoons during El Niño?', NULL, NULL, NULL, NULL, 'Storms form farther away and wind patterns suppress development', 'The correct term is: Storms form farther away and wind patterns suppress development.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'Why does the Philippines usually get more typhoons during La Niña?', NULL, NULL, NULL, NULL, 'Conditions become more favorable; storms form closer to the country', 'The correct term is: Conditions become more favorable; storms form closer to the country.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'Which Philippine industries are most harmed by El Niño drought?', NULL, NULL, NULL, NULL, 'Farming: rice, corn, and coconut production', 'The correct term is: Farming: rice, corn, and coconut production.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'List three common impacts of El Niño in the Philippines.', NULL, NULL, NULL, NULL, 'Drought, water shortage, crop damage', 'The correct term is: Drought, water shortage, crop damage.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'List three common impacts of La Niña in the Philippines.', NULL, NULL, NULL, NULL, 'Heavier rain, more floods, more typhoons', 'The correct term is: Heavier rain, more floods, more typhoons.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'Why do different countries experience different effects from El Niño and La Niña?', NULL, NULL, NULL, NULL, 'They change global wind and rain patterns differently in each place', 'The correct term is: They change global wind and rain patterns differently in each place.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'Why do government agencies monitor ENSO closely?', NULL, NULL, NULL, NULL, 'To issue warnings and prepare for disasters', 'The correct term is: To issue warnings and prepare for disasters.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What does a “neutral” ENSO condition mean?', NULL, NULL, NULL, NULL, 'Ocean and weather conditions are near their long-term average', 'The correct term is: Ocean and weather conditions are near their long-term average.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What is the Walker Circulation?', NULL, NULL, NULL, NULL, 'The large east-west cycle of rising and sinking air across the tropical Pacific', 'The correct term is: The large east-west cycle of rising and sinking air across the tropical Pacific.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'Why does rain fall on the eastern Pacific instead of the Philippines during El Niño?', NULL, NULL, NULL, NULL, 'The main rain belt follows the shifted warm water eastward', 'The correct term is: The main rain belt follows the shifted warm water eastward.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'How does climate change affect El Niño and La Niña events?', NULL, NULL, NULL, NULL, 'It makes them stronger and more frequent', 'The correct term is: It makes them stronger and more frequent.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What is the correct sequence leading to dry weather in the Philippines during El Niño?', NULL, NULL, NULL, NULL, 'Trade winds weaken → warm water shifts east → rain belt moves away → less rainfall', 'The correct term is: Trade winds weaken → warm water shifts east → rain belt moves away → less rainfall.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'How does El Niño affect Metro Manila’s water supply?', NULL, NULL, NULL, NULL, 'It reduces rainfall that fills major dams like Angat and Ipo', 'The correct term is: It reduces rainfall that fills major dams like Angat and Ipo.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'How do El Niño and La Niña change typhoon paths toward the Philippines?', NULL, NULL, NULL, NULL, 'El Niño: storms turn away; La Niña: more storms hit land', 'The correct term is: El Niño: storms turn away; La Niña: more storms hit land.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'What were some major effects of the strong 2015–2016 El Niño in the Philippines?', NULL, NULL, NULL, NULL, 'Severe drought, record heat, and large crop losses', 'The correct term is: Severe drought, record heat, and large crop losses.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'How do El Niño and La Niña affect the monsoon seasons?', NULL, NULL, NULL, NULL, 'El Niño weakens the southwest monsoon; La Niña strengthens it', 'The correct term is: El Niño weakens the southwest monsoon; La Niña strengthens it.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'Why do impacts vary from one El Niño event to another?', NULL, NULL, NULL, NULL, 'Differences in strength, location of warm water, and background climate', 'The correct term is: Differences in strength, location of warm water, and background climate.', true),
('b0000000-0000-0000-0000-000000000205', 3, 'post_test', 'Why is it important for students to learn about ENSO?', NULL, NULL, NULL, NULL, 'It helps understand and prepare for changes in food, water, and weather', 'The correct term is: It helps understand and prepare for changes in food, water, and weather.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What term describes actions that reduce or prevent greenhouse gas emissions?', NULL, NULL, NULL, NULL, 'Mitigation', 'The correct term is: Mitigation.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What term describes actions that adjust to changes already happening?', NULL, NULL, NULL, NULL, 'Adaptation', 'The correct term is: Adaptation.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What renewable energy uses heat from underground, abundant in the Philippines?', NULL, NULL, NULL, NULL, 'Geothermal energy', 'The correct term is: Geothermal energy.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What energy source uses flowing or falling water?', NULL, NULL, NULL, NULL, 'Hydroelectric power / hydropower', 'The correct term is: Hydroelectric power / hydropower.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What renewable energy comes directly from sunlight?', NULL, NULL, NULL, NULL, 'Solar energy', 'The correct term is: Solar energy.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What is the biggest source of greenhouse gas emissions in the Philippines?', NULL, NULL, NULL, NULL, 'Burning fossil fuels like coal, oil, and gas', 'The correct term is: Burning fossil fuels like coal, oil, and gas.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What simple action most reduces transport emissions?', NULL, NULL, NULL, NULL, 'Walk, bike, or take public transport instead of private cars', 'The correct term is: Walk, bike, or take public transport instead of private cars.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What do the three “R’s” of waste management stand for?', NULL, NULL, NULL, NULL, 'Reduce, Reuse, Recycle', 'The correct term is: Reduce, Reuse, Recycle.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'How do trees help fight climate change?', NULL, NULL, NULL, NULL, 'They absorb and store carbon dioxide', 'The correct term is: They absorb and store carbon dioxide.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'Give one observed effect of climate change already seen in the Philippines.', NULL, NULL, NULL, NULL, 'Stronger typhoons / longer droughts / rising sea levels', 'The correct term is: Stronger typhoons / longer droughts / rising sea levels.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'Which list contains renewable energy sources found in the Philippines?', NULL, NULL, NULL, NULL, 'Geothermal, hydro, solar, wind, biomass', 'The correct term is: Geothermal, hydro, solar, wind, biomass.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'How does switching to renewable energy help fight global warming?', NULL, NULL, NULL, NULL, 'It produces almost no carbon dioxide', 'The correct term is: It produces almost no carbon dioxide.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What is one effect of rising sea levels on Philippine coastal communities?', NULL, NULL, NULL, NULL, 'Coastal flooding, erosion, and saltwater damage', 'The correct term is: Coastal flooding, erosion, and saltwater damage.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'Why does using energy-efficient appliances help the climate?', NULL, NULL, NULL, NULL, 'Less electricity used means less fuel burned at power plants', 'The correct term is: Less electricity used means less fuel burned at power plants.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What is one effective way households can lower their carbon footprint?', NULL, NULL, NULL, NULL, 'Reduce wasted electricity and use efficient appliances', 'The correct term is: Reduce wasted electricity and use efficient appliances.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'How does separating and composting waste help reduce greenhouse gases?', NULL, NULL, NULL, NULL, 'It prevents methane from forming in landfills', 'The correct term is: It prevents methane from forming in landfills.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What is the purpose of the Renewable Energy Act of 2008?', NULL, NULL, NULL, NULL, 'To increase the use of local renewable energy', 'The correct term is: To increase the use of local renewable energy.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'How does climate change affect Philippine farming?', NULL, NULL, NULL, NULL, 'Unpredictable weather damages crops and threatens food supply', 'The correct term is: Unpredictable weather damages crops and threatens food supply.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'Why are mangroves and coral reefs considered important for climate action?', NULL, NULL, NULL, NULL, 'They store carbon and protect coasts from storms and rising seas', 'The correct term is: They store carbon and protect coasts from storms and rising seas.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What is the national target for renewable energy share in the Philippines by 2040?', NULL, NULL, NULL, NULL, '50%', 'The correct term is: 50%.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'Give one example each of mitigation and adaptation.', NULL, NULL, NULL, NULL, 'Mitigation: use solar power; Adaptation: plant flood-resistant crops', 'The correct term is: Mitigation: use solar power; Adaptation: plant flood-resistant crops.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'Why is geothermal energy especially useful for the Philippines?', NULL, NULL, NULL, NULL, 'It provides reliable power 24 hours a day using local resources', 'The correct term is: It provides reliable power 24 hours a day using local resources.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'Why is adaptation still needed even if we cut emissions?', NULL, NULL, NULL, NULL, 'Some warming and sea-level rise are already unavoidable', 'The correct term is: Some warming and sea-level rise are already unavoidable.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'How does expanding renewable energy help the Philippine economy?', NULL, NULL, NULL, NULL, 'It saves money on imported fuel and creates local jobs', 'The correct term is: It saves money on imported fuel and creates local jobs.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What household action helps both reduce emissions and cope with hotter weather?', NULL, NULL, NULL, NULL, 'Planting shade trees or collecting rainwater', 'The correct term is: Planting shade trees or collecting rainwater.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'Is there enough renewable energy available to power the entire Philippines?', NULL, NULL, NULL, NULL, 'Yes; our natural resources are more than sufficient', 'The correct term is: Yes; our natural resources are more than sufficient.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What does “climate justice” mean for the Philippines?', NULL, NULL, NULL, NULL, 'We contribute very little to emissions but are among the most affected countries', 'The correct term is: We contribute very little to emissions but are among the most affected countries.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'How does saving electricity help reduce climate impacts?', NULL, NULL, NULL, NULL, 'Less coal or gas is burned, so fewer greenhouse gases are released', 'The correct term is: Less coal or gas is burned, so fewer greenhouse gases are released.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'What is the main barrier to faster renewable energy adoption in the Philippines?', NULL, NULL, NULL, NULL, 'Existing contracts, slow approval, and grid limitations', 'The correct term is: Existing contracts, slow approval, and grid limitations.', true),
('b0000000-0000-0000-0000-000000000206', 3, 'post_test', 'Why is it important for Grade 10 students to learn about sustainability?', NULL, NULL, NULL, NULL, 'They will shape the future policies and face the effects of climate change', 'The correct term is: They will shape the future policies and face the effects of climate change.', true);
